import React, { useEffect, useState } from "react";
import axios from "axios";
import toast from "react-hot-toast";

export default function FeeStructure() {
  const [structure, setStructure] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios.get("http://localhost:5000/api/fees")
      .then(res => {
        if (res.data.success) setStructure(res.data.data);
      })
      .catch(() => toast.error("Failed to load fee structure"))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <p>Loading fee structure...</p>;
  if (!structure) return <p>No fee structure available.</p>;

  // Handle categories or fallback to items
  const categories = structure.categories || [{ title: "Fees", items: Object.values(structure.items || {}) }];

  return (
    <div className="page-container">
      <div className="fee-card">
        <h2>School Fee Structure ({structure.academicYear})</h2>
        <div dangerouslySetInnerHTML={{ __html: structure.notes }} />

        {categories.map(cat => {
          const catTotal = cat.items.reduce((sum, i) => sum + (i.amount || 0), 0);
          return (
            <div key={cat.title} className="fee-category">
              <h4>{cat.title}</h4>
              <table className="fee-table">
                <thead>
                  <tr>
                    <th>Particulars</th>
                    <th>Amount (₹)</th>
                  </tr>
                </thead>
                <tbody>
                  {cat.items.map(it => (
                    <tr key={it.key || it.title}>
                      <td>{it.title}</td>
                      <td>₹{it.amount}</td>
                    </tr>
                  ))}
                  <tr>
                    <td><b>Category Total</b></td>
                    <td><b>₹{catTotal}</b></td>
                  </tr>
                </tbody>
              </table>
            </div>
          );
        })}
      </div>
    </div>
  );
}
